import{_ as r,a0 as p,w as c,s as l,ao as i,I as o,a1 as s,A as n,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何使用 Watchtower 自動更新正在運行的 Docker 容器 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Watchtower 自動更新正在運行的 Docker 容器 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Watchtower 自動更新正在運行的 Docker 容器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Watchtower 自動更新正在運行的 Docker 容器 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220727 How To Automatically Update Running Docker Containers Using Watchtower","title":"如何使用 Watchtower 自動更新正在運行的 Docker 容器","tag":"202208","desc":""},"relativePath":"202208/20220727 How To Automatically Update Running Docker Containers Using Watchtower.md","filePath":"[post].md"}'),d={name:"202208/20220727 How To Automatically Update Running Docker Containers Using Watchtower.md"};function h(k,e,u,g,w,b){const t=p("Link");return c(),l("div",null,[e[20]||(e[20]=i('<h1 id="如何使用-watchtower-自動更新正在運行的-docker-容器" tabindex="-1">如何使用 Watchtower 自動更新正在運行的 Docker 容器 <a class="header-anchor" href="#如何使用-watchtower-自動更新正在運行的-docker-容器" aria-label="Permalink to “如何使用 Watchtower 自動更新正在運行的 Docker 容器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/13/171633bitrd5imi953bbbi.jpg" alt=""></p><blockquote><p>使用 Watchtower 自動更新 Docker 容器基礎鏡像</p></blockquote><p>對開發運維人員來説，保持 Docker 容器為最新版本是重要工作之一。手動更新 Docker 容器是一項耗時的工作。這篇文章解釋了 <strong>Watchtower</strong> 是什麼，如何安裝它，以及在 Linux 中如何 <strong>使用 Watchtower 自動更新正在運行的 Docker 容器</strong> 。</p><h3 id="watchtower-是什麼" tabindex="-1">Watchtower 是什麼？ <a class="header-anchor" href="#watchtower-是什麼" aria-label="Permalink to “Watchtower 是什麼？”">​</a></h3><p><strong>Watchtower</strong> 是一款自由開源的應用，用來監控運行中的 Docker 容器，並且當它發現基礎鏡像被更改後，可以自動的更新容器。</p><p>若 Watchtower 發現一個運行中的容器需要更新，它會以發送 SIGTERM 信號的方式，優雅的結束運行中容器的運行。</p><p>它會下載新鏡像，然後以最初部署時使用的方式，重啓容器。所有文件會在後台自動下載，因此不需要用户的介入。</p><p>在這份指南中，我們將會明白如何在類 Unix 系統中使用 Watchtower 自動更新正在運行的 Docker 容器。</p><p>我已經在 CentOS 和 Ubuntu 中測試了這份指南，所有的 Linux 發行版中操作過程都一樣。</p><h3 id="在-linux-中安裝-watchtower" tabindex="-1">在 Linux 中安裝 Watchtower <a class="header-anchor" href="#在-linux-中安裝-watchtower" aria-label="Permalink to “在 Linux 中安裝 Watchtower”">​</a></h3><p>可以通過 Docker 鏡像的方式下載 Watchtower 。因此，部署它是小事一樁。在你的 Linux 中安裝 Docker 鏡像，然後運行 Watchtower 立即開始監控 Docker 容器。</p><p>參考下方指導在基於 PRM 和 DEB 包管理系統中安裝 Docker</p>',13)),o("ul",null,[o("li",null,[s(t,{href:"https://ostechnix.com/install-docker-centos/"},{default:n(()=>[...e[0]||(e[0]=[a("如何在 CentOS 中安裝 Docker",-1)])]),_:1})]),o("li",null,[s(t,{href:"https://ostechnix.com/install-docker-ubuntu/"},{default:n(()=>[...e[1]||(e[1]=[a("如何在 Ubuntu 中安裝 Docker",-1)])]),_:1})]),o("li",null,[s(t,{href:"https://ostechnix.com/docker-desktop-for-linux/"},{default:n(()=>[...e[2]||(e[2]=[a("適用於 Linux 的 Docker 桌面初學者手冊",-1)])]),_:1})])]),e[21]||(e[21]=i(`<p>安裝 Docker 後，你可以使用以下命令以 <code>root</code> 用户身份部署 Watchtower 容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># docker run -d --name watchtower -v /var/run/docker.sock:/var/run/docker.sock containrrr/watchtower</span></span></code></pre></div><p>如果你已經安裝了 Docker 桌面版，以普通用户運行 Watchtower 容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run -d --name watchtower -v /var/run/docker.sock:/var/run/docker.sock containrrr/watchtower</span></span></code></pre></div><p>該命令會拉取最新版的 <code>watchtower</code> 鏡像，並運行 <code>watchtower</code> 容器。</p><p>輸出樣例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Unable to find image &#39;containrrr/watchtower:latest&#39; locally</span></span>
<span class="line"><span>latest: Pulling from containrrr/watchtower</span></span>
<span class="line"><span>1045b2f97fda: Pull complete </span></span>
<span class="line"><span>35a104a262d3: Pull complete </span></span>
<span class="line"><span>1a0671483169: Pull complete </span></span>
<span class="line"><span>Digest: sha256:bbf9794a691b59ed2ed3089fec53844f14ada249ee5e372ff0e595b73f4e9ab3</span></span>
<span class="line"><span>Status: Downloaded newer image for containrrr/watchtower:latest</span></span>
<span class="line"><span>91c104ef0e9896e8cd5ff30d9f13e728dbfad66443830ec2ac85dde6d7d37564</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Run-Watchtower-Docker-Container.png" alt="Run Watchtower Docker Container"></p><h3 id="使用-watchtower-自動更新-docker-容器" tabindex="-1">使用 Watchtower 自動更新 Docker 容器 <a class="header-anchor" href="#使用-watchtower-自動更新-docker-容器" aria-label="Permalink to “使用 Watchtower 自動更新 Docker 容器”">​</a></h3><p>在你的系統上，Watchtower 正在和其他容器一起運行。你可以使用一下命令查看運行中的 Docker 容器列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker ps</span></span></code></pre></div><p>輸出樣例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CONTAINER ID   IMAGE                       COMMAND                  CREATED          STATUS          PORTS                                         NAMES</span></span>
<span class="line"><span>91c104ef0e98   containrrr/watchtower       &quot;/watchtower&quot;            14 minutes ago   Up 14 minutes   8080/tcp                                      watchtower</span></span>
<span class="line"><span>f90b462b0712   bitnami/wordpress-nginx:6   &quot;/opt/bitnami/script…&quot;   19 minutes ago   Up 19 minutes   0.0.0.0:80-&gt;8080/tcp, 0.0.0.0:443-&gt;8443/tcp   ostechnix-wordpress-1</span></span></code></pre></div><p>正如上方輸出所示，<code>watchtower</code> 容器正在和名為 <code>ostechnix-wordpress-1</code> 的容器一起運行。從現在開始，<code>watchtower</code> 會每隔幾分鐘會檢查該容器。</p><p>如果 Watchtower 發現該容器的基礎鏡像的任何變化，它會優雅的關閉 <code>ostechnix-wordpress-1</code> 容器，然後使用與最初啓動它時使用的相同方式，啓動新的鏡像。</p><p>類似的，它會自動地每隔幾分鐘檢查所有的運行中容器，並自動更新它們。</p><h3 id="watchtower-如何更新多連接的容器" tabindex="-1">Watchtower 如何更新多連接的容器？ <a class="header-anchor" href="#watchtower-如何更新多連接的容器" aria-label="Permalink to “Watchtower 如何更新多連接的容器？”">​</a></h3><p>在監視多連接容器時，Watchtower 十分智能。</p><p>假設我們現在運行兩個容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker ps</span></span></code></pre></div><p>輸出樣例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CONTAINER ID   IMAGE                       COMMAND                  CREATED          STATUS          PORTS                                         NAMES</span></span>
<span class="line"><span>91c104ef0e98   containrrr/watchtower       &quot;/watchtower&quot;            14 minutes ago   Up 14 minutes   8080/tcp                                      watchtower</span></span>
<span class="line"><span>f90b462b0712   bitnami/wordpress-nginx:6   &quot;/opt/bitnami/script…&quot;   19 minutes ago   Up 19 minutes   0.0.0.0:80-&gt;8080/tcp, 0.0.0.0:443-&gt;8443/tcp   ostechnix-wordpress-1</span></span>
<span class="line"><span>a895f082438a   bitnami/mariadb:10.6        &quot;/opt/bitnami/script…&quot;   20 minutes ago   Up 19 minutes   3306/tcp                                      ostechnix-mariadb-1</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/View-Running-Docker-Containers.png" alt="View Running Docker Containers"></p><p>正如你看到的，我們正在運行 <code>ostechnix-wordpress-1</code> 和 <code>ostechnix-mariadb-1</code> 這兩個容器。<code>ostechnix-mariadb-1</code> 容器鏈接到 <code>ostechnix-wordpress-1</code> 容器。</p><p>如果 Watchtower 發現 <code>ostechnix-wordpress-1</code> 容器有個新版本，它會先關閉與之相連接的 <code>ostechnix-mariadb-1</code> 容器 ，然後才會關閉 <code>ostechnix-wordpress-1</code> 容器。</p><p>更新 <code>ostechnix-wordpress-1</code> 容器後，Watchtower 會以正確的順序，且與最初啓動它們時使用的相同方式，重啓這兩個容器，以便應用程序正確恢復。在我們的例子中，首先啓動的是 <code>ostechnix-mariadb-1</code> 容器，然後是 <code>ostechnix-wordpress-1</code> 容器，以確保連接能夠繼續運行。</p><h3 id="監控特定容器" tabindex="-1">監控特定容器 <a class="header-anchor" href="#監控特定容器" aria-label="Permalink to “監控特定容器”">​</a></h3><p>默認情況下，Watchtower 將監控在它所指向的 Docker 守護進程中運行的所有 Docker 容器。</p><p>不過，你可以像下面這樣，通過指定容器名稱限制 Watchtower 監視特定的 Docker 容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run -d --name watchtower -v /var/run/docker.sock:/var/run/docker.sock containrrr/watchtower ostechnix-wordpress-1</span></span></code></pre></div><p>在上方的例子中，<code>watchtower</code> 會忽略其他容器，只監視名為 <code>ostechnix-wordpress-1</code> 的容器更新情況。</p><p>如果你不指定任何參數，Watchtower 會照常監視所有運行中的 Docker 容器。</p><h3 id="發送提示" tabindex="-1">發送提示 <a class="header-anchor" href="#發送提示" aria-label="Permalink to “發送提示”">​</a></h3><p>或許你想收到容器更新的通知。你可以通過電子郵件、Slack 、MSTeams 以及 Gotify 發送通知。</p><p>下面這個例子展示瞭如何通過電子郵件發送通知。假設你已經設置了 SMTP 服務器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker run -d \\</span></span>
<span class="line"><span>  --name watchtower \\</span></span>
<span class="line"><span>  -v /var/run/docker.sock:/var/run/docker.sock \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATIONS=email \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_FROM=fromaddress@gmail.com \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_TO=toaddress@gmail.com \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_SERVER=smtp.gmail.com \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_SERVER_PORT=587 \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_SERVER_USER=fromaddress@gmail.com \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_SERVER_PASSWORD=app_password \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_DELAY=2 \\</span></span>
<span class="line"><span>  containrrr/watchtower</span></span></code></pre></div><p>參考下方 Watchtower Github 倉庫和 Watchtower 官方主頁獲取更多信息：</p><h3 id="資料" tabindex="-1">資料 <a class="header-anchor" href="#資料" aria-label="Permalink to “資料”">​</a></h3>`,38)),o("ul",null,[o("li",null,[s(t,{href:"https://github.com/v2tec/watchtower"},{default:n(()=>[...e[3]||(e[3]=[a("Watchtower GitHub",-1)])]),_:1})]),o("li",null,[s(t,{href:"https://containrrr.dev/watchtower/"},{default:n(()=>[...e[4]||(e[4]=[a("Watchtower 主頁",-1)])]),_:1})])]),e[22]||(e[22]=o("hr",null,null,-1)),o("p",null,[e[6]||(e[6]=a("via: ",-1)),s(t,{href:"https://ostechnix.com/automatically-update-running-docker-containers/"},{default:n(()=>[...e[5]||(e[5]=[a("https://ostechnix.com/automatically-update-running-docker-containers/",-1)])]),_:1})]),o("p",null,[e[11]||(e[11]=a("作者：",-1)),s(t,{href:"https://ostechnix.com/author/sk/"},{default:n(()=>[...e[7]||(e[7]=[a("sk",-1)])]),_:1}),e[12]||(e[12]=a(" 選題：",-1)),s(t,{href:"https://github.com/lkxed"},{default:n(()=>[...e[8]||(e[8]=[a("lkxed",-1)])]),_:1}),e[13]||(e[13]=a(" 譯者：",-1)),s(t,{href:"https://github.com/Donkey-Hao"},{default:n(()=>[...e[9]||(e[9]=[a("Donkey",-1)])]),_:1}),e[14]||(e[14]=a(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[10]||(e[10]=[a("wxy",-1)])]),_:1})]),o("p",null,[e[17]||(e[17]=a("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[15]||(e[15]=[a("LCTT",-1)])]),_:1}),e[18]||(e[18]=a(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:n(()=>[...e[16]||(e[16]=[a("Linux中國",-1)])]),_:1}),e[19]||(e[19]=a(" 榮譽推出",-1))])])}const x=r(d,[["render",h]]);export{T as __pageData,x as default};
